<?php
require_once __DIR__ . '/config/config.php';
require_once __DIR__ . '/app/helpers/helpers.php';
require_once __DIR__ . '/config/database.php';
require_once __DIR__ . '/app/services/RecommendationService.php';

$pdo = db();
$q = trim($_GET['q'] ?? '');
$modality = trim($_GET['modality'] ?? '');
$experience = trim($_GET['experience'] ?? '');

$sql = 'SELECT j.*, c.name as company_name FROM jobs j LEFT JOIN companies c ON c.id=j.company_id WHERE j.status="active"';
$params = [];
if ($q !== '') {
    $sql .= ' AND (j.title LIKE :q OR j.description LIKE :q OR j.technology LIKE :q OR c.name LIKE :q)';
    $params['q'] = '%' . $q . '%';
}
if (in_array($modality, ['Remoto', 'Presencial', 'Híbrido'], true)) {
    $sql .= ' AND j.modality = :modality';
    $params['modality'] = $modality;
}
if (in_array($experience, ['Junior', 'Mid', 'Senior'], true)) {
    $sql .= ' AND j.experience_required = :experience';
    $params['experience'] = $experience;
}
$sql .= ' ORDER BY j.id DESC';
$stmt = $pdo->prepare($sql); $stmt->execute($params); $jobs = $stmt->fetchAll();

$matchMap = [];
if (!empty($_SESSION['user']) && ($_SESSION['user']['role'] ?? '') === 'talent') {
    $matchMap = RecommendationService::recommend((int)$_SESSION['user']['id'], $jobs);
}
?>
